// Print the HTML edition generated by scripts/build-user-manual.py.
import { chromium } from "@playwright/test";
import { mkdir, unlink } from "node:fs/promises";
import { execFileSync } from "node:child_process";
import path from "node:path";
// Serve dist over HTTP (for example: python -m http.server 8765 --directory
// docs/user-manual/dist) so Chromium can load local figure files reliably.
const input = process.env.MANUAL_PRINT_URL ?? "http://127.0.0.1:8765/print.html";
const output = path.resolve("output/pdf/easy2u-user-manual-en-internal.pdf");
const preliminary = path.resolve("tmp/pdfs/easy2u-preliminary.pdf");
await mkdir(path.dirname(output), { recursive: true });
await mkdir(path.dirname(preliminary), { recursive: true });
const pdfOptions = {
  preferCSSPageSize: true,
  printBackground: true,
  tagged: true,
  outline: true,
  displayHeaderFooter: true,
  headerTemplate: "<span></span>",
  footerTemplate: '<div style="width:100%;margin:0 17mm;color:#75665b;font:8pt Segoe UI,Arial,sans-serif;display:flex;justify-content:space-between"><span>Easy2U user manual - English internal edition</span><span><span class="pageNumber"></span> / <span class="totalPages"></span></span></div>',
};

function chapterPages(pdfPath, count) {
  return JSON.parse(execFileSync("python", ["scripts/map-user-manual-pages.py", pdfPath, String(count)], { encoding: "utf8" }));
}

const browser = await chromium.launch({ headless: true });
try {
  const page = await browser.newPage();
  await page.goto(input, { waitUntil: "networkidle" });
  await page.evaluate(() => document.fonts.ready);
  const broken = await page.locator("img").evaluateAll((images) => images.filter((image) => !image.complete || !image.naturalWidth).map((image) => image.src));
  if (broken.length) throw new Error(`Missing PDF images: ${broken.join(", ")}`);
  const chapterCount = await page.locator(".toc-page").count();
  await page.pdf({ ...pdfOptions, path: preliminary });
  let numbers = chapterPages(preliminary, chapterCount);
  for (let pass = 0; pass < 3; pass += 1) {
    await page.locator(".toc-page").evaluateAll((spans, pages) => {
      spans.forEach((span, index) => { span.textContent = String(pages[index]); });
    }, numbers);
    await page.pdf({ ...pdfOptions, path: output });
    const actual = chapterPages(output, chapterCount);
    if (actual.every((value, index) => value === numbers[index])) break;
    if (pass === 2) throw new Error("PDF contents page numbers did not stabilize");
    numbers = actual;
  }
  console.log(output);
} finally {
  await browser.close();
  await unlink(preliminary).catch(() => {});
}
